import { search, DEFAULT_BOUNDS } from './search';
import type { Grammar, PDA } from './types';

export interface Comparison {
  sigma: string[];
  /** every string of length 0..maxLen was checked */
  maxLen: number;
  total: number;
  /** generated by the grammar but not in the target language (shortest first) */
  extra: string[];
  /** in the target language but not generated by the grammar */
  missing: string[];
  /** in the target language, but the search hit its limit so the grammar's answer is unknown */
  unknown: string[];
}

/**
 * Compare a grammar (through its PDA) with a target language given as a membership test.
 * Runs every string over the alphabet up to the longest length that fits `budget` strings.
 * Agreement on all of them is strong evidence of equivalence, not a proof.
 */
export function compareWithTarget(g: Grammar, pda: PDA, targetSigma: string[], accepts: (w: string) => boolean, budget = 520): Comparison {
  const sigma = [...new Set([...targetSigma, ...g.terminals])];
  let maxLen = 0;
  let layer = 1;
  let total = 1;
  while (maxLen < 12 && sigma.length > 0 && total + layer * sigma.length <= budget) {
    layer *= sigma.length;
    total += layer;
    maxLen++;
  }
  const extra: string[] = [];
  const missing: string[] = [];
  const unknown: string[] = [];
  let level = [''];
  for (let len = 0; len <= maxLen; len++) {
    for (const w of level) {
      const r = search(g, pda, Array.from(w), DEFAULT_BOUNDS);
      const got = r.verdict.kind === 'accepted';
      const want = accepts(w);
      if (got && !want) extra.push(w);
      else if (!got && want) (r.verdict.kind === 'inconclusive' ? unknown : missing).push(w);
    }
    if (len < maxLen) level = level.flatMap((s) => sigma.map((c) => s + c));
  }
  return { sigma, maxLen, total, extra, missing, unknown };
}
